namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }

    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please provide a short description.")]
    [StringLength(300, ErrorMessage = "Description must be 300 characters or fewer.")]
    public string Description { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = GetSeedRecipes();
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<string> Categories =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void RateRecipe(int id, int stars)
    {
        var recipe = GetById(id);
        if (recipe is null || stars is < 1 or > 5) return;
        recipe.TotalRatingPoints += stars;
        recipe.RatingCount++;
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Description = submission.Description,
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        });
    }

    private static List<Recipe> GetSeedRecipes() =>
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple yet delicious pizza with fresh basil and mozzarella.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute over sauce.", "Bake for 10–12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
            TotalRatingPoints = 23, RatingCount = 5
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta made with eggs, cheese, and guanciale.",
            Ingredients = ["Spaghetti", "Guanciale or pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps = ["Cook pasta in salted water until al dente.", "Crisp guanciale in a skillet.", "Whisk eggs with grated pecorino and pepper.", "Toss hot pasta with guanciale off heat.", "Pour egg mixture over pasta and toss quickly.", "Serve immediately with extra cheese."],
            TotalRatingPoints = 18, RatingCount = 4
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer.", "Stir in cream and garam masala.", "Add chicken and simmer 10 minutes."],
            TotalRatingPoints = 14, RatingCount = 3
        },
        new()
        {
            Id = 4, Title = "Vegetable Samosas", Category = "Indian",
            Description = "Crispy pastry filled with spiced potatoes and peas.",
            Ingredients = ["Potatoes", "Green peas", "Cumin seeds", "Coriander powder", "Flour", "Oil for frying"],
            Steps = ["Boil and mash potatoes.", "Sauté cumin, add peas and spices.", "Mix with potatoes for filling.", "Prepare dough, roll and cut into semicircles.", "Fill and fold into triangles, seal edges.", "Deep fry until golden brown."],
            TotalRatingPoints = 9, RatingCount = 2
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in corn tortillas with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = ["Brown ground beef and drain fat.", "Add taco seasoning with water and simmer.", "Warm tortillas in a dry skillet.", "Fill tortillas with beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa."],
            TotalRatingPoints = 20, RatingCount = 5
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh avocado dip with lime, cilantro, and a kick of jalapeño.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Salt", "Tomato"],
            Steps = ["Halve and pit avocados, scoop into a bowl.", "Mash to desired consistency.", "Stir in diced onion, tomato, jalapeño, and cilantro.", "Add lime juice and salt to taste.", "Serve immediately with tortilla chips."],
            TotalRatingPoints = 12, RatingCount = 3
        },
        new()
        {
            Id = 7, Title = "Miso Ramen", Category = "Japanese",
            Description = "Rich miso broth with noodles, pork, and a soft-boiled egg.",
            Ingredients = ["Ramen noodles", "Miso paste", "Chicken broth", "Pork belly", "Soft-boiled egg", "Green onions", "Nori", "Sesame oil"],
            Steps = ["Simmer broth and whisk in miso paste.", "Sear sliced pork belly until caramelized.", "Cook ramen noodles according to package.", "Ladle broth into bowls, add noodles.", "Top with pork, halved egg, green onions, and nori."],
            TotalRatingPoints = 15, RatingCount = 3
        },
        new()
        {
            Id = 8, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Individual cakes with a molten chocolate center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F and grease ramekins.", "Melt chocolate and butter together.", "Whisk eggs and sugar until thick.", "Fold in chocolate mixture, then flour.", "Pour into ramekins and bake 12–14 minutes.", "Invert onto plates and serve immediately."],
            TotalRatingPoints = 19, RatingCount = 4
        },
        new()
        {
            Id = 9, Title = "Tiramisu", Category = "Desserts",
            Description = "Classic Italian layered dessert with coffee-soaked ladyfingers.",
            Ingredients = ["Ladyfingers", "Espresso", "Mascarpone", "Eggs", "Sugar", "Cocoa powder", "Marsala wine"],
            Steps = ["Brew espresso and let cool; add Marsala.", "Separate eggs; whisk yolks with sugar.", "Fold mascarpone into yolk mixture.", "Beat egg whites to stiff peaks and fold in.", "Dip ladyfingers in espresso and layer in dish.", "Spread cream, repeat layers, dust with cocoa.", "Refrigerate at least 4 hours before serving."],
            TotalRatingPoints = 22, RatingCount = 5
        },
    ];
}

