@page "/"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>RecipeHub — Home</PageTitle>

<h1>Welcome to RecipeHub 🍳</h1>
<p class="lead">Discover and share your favourite recipes with the community.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in RecipeService.Categories)
    {
        <div class="col-md-4 col-sm-6 mb-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body d-flex flex-column">
                    <h4 class="card-title">@CategoryEmoji(category) @category</h4>
                    <p class="card-text text-muted">
                        @RecipeService.GetByCategory(category).Count recipe(s)
                    </p>
                    <a href="@($"category/{category.ToLowerInvariant()}")" class="btn btn-outline-primary mt-auto">
                        View Recipes →
                    </a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Mexican" => "🇲🇽",
        "Japanese" => "🇯🇵",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

