<h1>Submit a Recipe</h1>
<p>Share your favourite recipe with the community!</p>

@if (SubmittedTitle is not null)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> "@SubmittedTitle" has been added.
        <a href="/categories">Browse recipes</a> to find it.
    </div>
}

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="mt-3" style="max-width: 600px;">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="Model.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => Model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="Model.Category" class="form-select">
            <option value="">-- Select --</option>
            @foreach (var cat in RecipeService.Categories)
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => Model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="description" class="form-label">Short Description</label>
        <InputTextArea id="description" @bind-Value="Model.Description" class="form-control" rows="2" placeholder="A brief description of your recipe" />
        <ValidationMessage For="() => Model.Description" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients <small class="text-muted">(one per line)</small></label>
        <InputTextArea id="ingredients" @bind-Value="Model.Ingredients" class="form-control" rows="5" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => Model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps <small class="text-muted">(one per line)</small></label>
        <InputTextArea id="steps" @bind-Value="Model.Steps" class="form-control" rows="5" placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;..." />
        <ValidationMessage For="() => Model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeHub.Models.RecipeSubmission Model { get; set; } = new();
    private string? SubmittedTitle { get; set; }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(Model);
        SubmittedTitle = Model.Title;
        Model = new();
    }
}
