@page "/category/{CategoryName}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item"><a href="/categories">Categories</a></li>
        <li class="breadcrumb-item active" aria-current="page">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row mt-3">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <div class="mb-2">
                            @if (recipe.RatingCount > 0)
                            {
                                <span class="text-warning">
                                    @(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))
                                </span>
                                <small class="text-muted">(@recipe.RatingCount)</small>
                            }
                            else
                            {
                                <small class="text-muted">No ratings yet</small>
                            }
                        </div>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-sm btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<RecipeHub.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{RecipeId:int}"
@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@(Recipe.Category.ToLowerInvariant())">@Recipe.Category</a></li>
            <li class="breadcrumb-item active" aria-current="page">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <p class="lead">@Recipe.Description</p>

    <div class="mb-4">
        <StarRating RecipeId="Recipe.Id" CurrentAverage="Recipe.AverageRating" RatingCount="Recipe.RatingCount" />
    </div>

    <div class="row">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <h3>Instructions</h3>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in Recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }

    private RecipeHub.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(RecipeId);
    }
}

@* Interactive star-rating widget — rendered with Server interactivity *@
@rendermode InteractiveServer
@inject RecipeHub.Services.RecipeService RecipeService

<div class="d-inline-flex align-items-center" role="group" aria-label="Rate this recipe">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button type="button"
                class="btn btn-link text-decoration-none p-0 fs-4"
                style="cursor:pointer; color: @(star <= (HoverStar ?? DisplayStars) ? "#ffc107" : "#dee2e6");"
                title="@star star(s)"
                @onclick="() => SubmitRating(star)"
                @onmouseover="() => HoverStar = star"
                @onmouseout="() => HoverStar = null">
            ★
        </button>
    }
    <span class="ms-2 text-muted small">
        @if (Submitted)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        else if (RatingCount > 0)
        {
            @($"{CurrentAverage:F1} ({RatingCount} rating{(RatingCount == 1 ? "" : "s")})")
        }
        else
        {
            @("Be the first to rate!")
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int? HoverStar { get; set; }
    private bool Submitted { get; set; }

    private int DisplayStars => (int)Math.Round(CurrentAverage);

    private void SubmitRating(int stars)
    {
        RecipeService.RateRecipe(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentAverage = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        Submitted = true;
    }
}

